describe("Python nominal IGNORECASE predicate parity", () => {
  // Defect: JS iu lacks Python's dotted/dotless I equivalence for this fixed ASCII rejection predicate.
  it.each(cases)("$name", c => {
    const base = originalCases[0];
    const old = c.slot === "mark" ? "diamond" : c.slot === "state" ? base.state : base.operation;
    const body = base.body.replaceAll(old, c.body_value ?? c.value);
    expect(createHash("sha256").update(body).digest("hex")).toBe(c.sha256);
    const reading = replayContextReading(body, c.slot === "operation" ? c.value : base.operation, c.slot === "state" ? c.value : base.state, c.sha256);
    if (!c.accepted) expect(reading).toBeNull();
    else {
      expect(reading).not.toBeNull();
      expect(reading?.source_body).toBe(body);
      const clauses = reading?.clause_inventory as { literal: string; source_range: { start: number; end: number } }[];
      for (const clause of clauses) expect(Array.from(body).slice(clause.source_range.start, clause.source_range.end).join("" )).toBe(clause.literal);
    }
  });
});
